import java.io.BufferedInputStream

fun main() {
    val input = BufferedInputStream(System.`in`).readBytes()
    var pos = 0
    fun ni(): Int {
        while (input[pos] < '0'.code.toByte()) pos++
        var r = 0
        while (pos < input.size && input[pos] >= '0'.code.toByte()) {
            r = r * 10 + (input[pos] - '0'.code.toByte()); pos++
        }
        return r
    }
    val n = ni(); val k = ni()
    val a = IntArray(n) { ni() }
    val us = IntArray(n - 1); val vs = IntArray(n - 1)
    val deg = IntArray(n + 1)
    for (i in 0 until n - 1) {
        val u = ni() - 1; val v = ni() - 1
        us[i] = u; vs[i] = v; deg[u]++; deg[v]++
    }
    val start = IntArray(n + 1)
    for (i in 0 until n) start[i + 1] = start[i] + deg[i]
    val adj = IntArray(2 * (n - 1))
    val idx = start.copyOf()
    for (i in 0 until n - 1) { adj[idx[us[i]]++] = vs[i]; adj[idx[vs[i]]++] = us[i] }
    val order = IntArray(n); val par = IntArray(n) { -1 }
    var head = 0; var tail = 0
    val visited = BooleanArray(n)
    order[tail++] = 0; visited[0] = true
    while (head < tail) {
        val u = order[head++]
        for (j in start[u] until start[u + 1]) {
            val w = adj[j]
            if (!visited[w]) { visited[w] = true; par[w] = u; order[tail++] = w }
        }
    }
    val sz = IntArray(n)
    for (i in n - 1 downTo 0) { val v = order[i]; sz[v]++; if (par[v] >= 0) sz[par[v]] += sz[v] }

    val f = IntArray(n); val sumFull = IntArray(n); val mn1 = IntArray(n)
    val mn2 = IntArray(n); val id1 = IntArray(n); val g = IntArray(n)

    fun check(x: Int): Boolean {
        for (i in n - 1 downTo 0) {
            val v = order[i]
            if (a[v] < x) { f[v] = 0; continue }
            var sf = 0; var m1 = 0; var m2 = 0; var i1 = -1
            for (j in start[v] until start[v + 1]) {
                val c = adj[j]
                if (c == par[v]) continue
                if (f[c] == sz[c]) sf += sz[c]
                else {
                    val fv = f[c]
                    if (fv > m1) { m2 = m1; m1 = fv; i1 = c } else if (fv > m2) m2 = fv
                }
            }
            sumFull[v] = sf; mn1[v] = m1; mn2[v] = m2; id1[v] = i1
            f[v] = 1 + sf + m1
        }
        val root = 0
        g[root] = 0
        for (i in 0 until n) {
            val p = order[i]
            val good = a[p] >= x
            for (j in start[p] until start[p + 1]) {
                val v = adj[j]
                if (v == par[p]) continue
                if (!good) { g[v] = 0; continue }
                var sf = sumFull[p]; var mx: Int
                if (f[v] == sz[v]) { sf -= sz[v]; mx = mn1[p] }
                else mx = if (id1[p] == v) mn2[p] else mn1[p]
                if (p != root) {
                    val psz = n - sz[p]
                    if (g[p] == psz) sf += psz else if (g[p] > mx) mx = g[p]
                }
                g[v] = 1 + sf + mx
            }
        }
        for (v in 0 until n) {
            if (a[v] < x) continue
            val value: Int
            if (v == root) value = f[v]
            else {
                var sf = sumFull[v]; var mx = mn1[v]
                val psz = n - sz[v]
                if (g[v] == psz) sf += psz else if (g[v] > mx) mx = g[v]
                value = 1 + sf + mx
            }
            if (value >= k) return true
        }
        return false
    }

    val sorted = a.clone(); sorted.sort()
    var lo = 0; var hi = n - 1; var ans = sorted[0]
    while (lo <= hi) {
        val mid = (lo + hi) ushr 1
        if (check(sorted[mid])) { ans = sorted[mid]; lo = mid + 1 } else hi = mid - 1
    }
    println(ans)
}
